<script setup>
import { reactive, ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTag from '../../../components/mds/MTag.vue';
const props=defineProps({tab:{type:String,default:'runs'},runs:{type:Array,default:()=>[]},competitors:{type:Array,default:()=>[]},campaigns:{type:Array,default:()=>[]},settings:{type:Object,default:()=>({})},canManage:Boolean,saving:Boolean,error:{type:String,default:''},selectedCampaign:Object,campaignResult:Object,evaluating:Boolean,safeAreaStyle:Object}); const emit=defineEmits(['back','tab','run-scan','create-competitor','edit-competitor','delete-competitor','save-competitor','create-campaign','edit-campaign','delete-campaign','save-campaign','select-campaign','evaluate-campaign','save-settings']);
const competitorForm=ref(null); const campaignForm=ref(null); const settingsDraft=reactive({autoscan:props.settings.autoscan===true,intervalHours:props.settings.intervalHours||4,scanDays:props.settings.scanDays||30});
watch(() => props.settings, (value) => { settingsDraft.autoscan=value?.autoscan===true; settingsDraft.intervalHours=value?.intervalHours||4; settingsDraft.scanDays=value?.scanDays||30; }, { deep:true });
function editCompetitor(record=null){competitorForm.value=record?{...record,channels:record.channels.join(', ')}:{name:'',website:'',fanpage:'',channels:'',note:''};} function editCampaign(record=null){campaignForm.value=record?{...record,keywords:record.keywords.join(', '),competitors:record.competitors.join(', ')}:{name:'',startDate:'',endDate:'',message:'',content:'',audience:'',status:'draft',note:'',keywords:'',competitors:''};} function submitCompetitor(){if(!competitorForm.value?.name?.trim())return;emit('save-competitor',competitorForm.value);competitorForm.value=null;} function submitCampaign(){if(!campaignForm.value?.name?.trim())return;emit('save-campaign',campaignForm.value);campaignForm.value=null;}
</script>
<template><section class="mds-mobile-app flex min-h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Vận hành giám sát" @back="emit('back')"/><main class="min-h-0 flex-1 overflow-y-auto pb-[var(--mds-mobile-safe-bottom)]"><div class="mds-mobile-gutter-x space-y-3 py-3"><div class="flex gap-2 overflow-x-auto pb-1"><MButton v-for="item in [['runs','Lượt quét'],['competitors','Đối thủ'],['campaigns','Chiến dịch'],['settings','Thiết lập']]" :key="item[0]" :variant="tab===item[0]?'primary':'neutral'" @click="emit('tab',item[0])">{{item[1]}}</MButton></div><p v-if="error" class="rounded-lg bg-[var(--mds-danger-bg)] p-3 text-[13px] text-[var(--mds-danger)]" role="alert">{{error}}</p><section v-if="tab==='runs'" class="space-y-3"><MButton v-if="canManage" variant="primary" class="w-full [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" @click="emit('run-scan')">Quét theo bộ đang bật</MButton><article v-for="run in runs" :key="run.id" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><div class="flex items-center justify-between gap-2"><strong>{{run.startedAt||'Lượt quét'}}</strong><MTag :color="run.status==='done'?'success':run.status==='error'?'danger':'warning'">{{run.status||'—'}}</MTag></div><p class="mt-2 text-[13px] text-[var(--mds-text-secondary)]">{{run.fetched}} bài · {{run.newMentions}} mới · {{run.analyzed}} đã chấm</p><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">Nguồn: {{run.triggeredBy||'system'}}</p></article><MEmptyState v-if="!runs.length" title="Chưa có lượt quét" description="Lịch sử sẽ xuất hiện sau khi quét."/></section><section v-else-if="tab==='competitors'" class="space-y-3"><MButton v-if="canManage" variant="primary" class="w-full [&]:h-[var(--mds-mobile-touch-target)]" @click="editCompetitor()">Thêm đối thủ</MButton><article v-for="record in competitors" :key="record.id" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><div class="flex items-start justify-between gap-2"><strong>{{record.name}}</strong><MTag color="neutral">{{record.channels.length}} kênh</MTag></div><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{record.website||record.fanpage||'Chưa có kênh liên kết'}}</p><p v-if="record.note" class="mt-2 text-[13px]">{{record.note}}</p><div v-if="canManage" class="mt-3 flex justify-end gap-2"><MButton variant="link" class="[&]:min-h-[var(--mds-mobile-touch-target)]" @click="editCompetitor(record)">Sửa</MButton><MButton variant="link" class="text-[var(--mds-danger)] [&]:min-h-[var(--mds-mobile-touch-target)]" @click="emit('delete-competitor',record)">Xóa</MButton></div></article><MEmptyState v-if="!competitors.length" title="Chưa có đối thủ" description="Thêm đối thủ để theo dõi."/></section><section v-else-if="tab==='campaigns'" class="space-y-3"><MButton v-if="canManage" variant="primary" class="w-full [&]:h-[var(--mds-mobile-touch-target)]" @click="editCampaign()">Thêm chiến dịch</MButton><article v-for="record in campaigns" :key="record.id" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><strong>{{record.name}}</strong><p class="mt-1 text-[12px] text-[var(--mds-text-secondary)]">{{record.startDate||'—'}} → {{record.endDate||'—'}}</p><div class="mt-3 flex flex-wrap gap-2"><MButton variant="neutral" @click="emit('select-campaign',record)">Xem kết quả</MButton><MButton v-if="canManage" variant="link" @click="editCampaign(record)">Sửa</MButton><MButton v-if="canManage" variant="link" class="text-[var(--mds-danger)]" @click="emit('delete-campaign',record)">Xóa</MButton></div></article><MEmptyState v-if="!campaigns.length" title="Chưa có chiến dịch" description="Tạo chiến dịch để theo dõi hiệu quả."/><article v-if="selectedCampaign" class="rounded-lg bg-[var(--mds-bg-page)] p-4"><div class="flex items-start justify-between gap-2"><strong class="min-w-0">{{selectedCampaign.name}}</strong><MButton variant="icon" :loading="evaluating" aria-label="AI đánh giá" @click="emit('evaluate-campaign',selectedCampaign)">AI</MButton></div><div v-if="campaignResult" class="mt-3 grid grid-cols-2 gap-2"><div v-for="item in [['Tổng tin',campaignResult.total],['Tích cực',campaignResult.sentiment?.positive],['Trung tính',campaignResult.sentiment?.neutral],['Tiêu cực',campaignResult.sentiment?.negative]]" :key="item[0]" class="rounded-lg bg-[var(--mds-bg)] p-3"><strong>{{item[1]||0}}</strong><p class="text-[12px]">{{item[0]}}</p></div></div><p v-if="campaignResult?.evaluation" class="mt-3 whitespace-pre-line text-[13px]">{{campaignResult.evaluation}}</p></article></section><section v-else class="rounded-lg bg-[var(--mds-bg-page)] p-4"><h2 class="text-[15px] font-semibold">Thiết lập quét</h2><div class="mt-4 space-y-3"><MSelect v-model="settingsDraft.autoscan" :options="[{value:true,label:'Bật tự động quét'},{value:false,label:'Tắt tự động quét'}]"/><MInput v-model="settingsDraft.intervalHours" type="number" placeholder="Số giờ giữa các lượt"/><MInput v-model="settingsDraft.scanDays" type="number" placeholder="Số ngày lấy dữ liệu"/><MButton variant="primary" class="w-full [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" @click="emit('save-settings',settingsDraft)">Lưu thiết lập</MButton></div></section></div></main><MDialog :model-value="Boolean(competitorForm)" :title="competitorForm?.id?'Sửa đối thủ':'Thêm đối thủ'" @update:model-value="!$event&&(competitorForm=null)" @confirm="emit('save-competitor',competitorForm);competitorForm=null"><div class="space-y-3"><MInput v-model="competitorForm.name" placeholder="Tên đối thủ"/><MInput v-model="competitorForm.website" placeholder="Website"/><MInput v-model="competitorForm.fanpage" placeholder="Fanpage"/><MInput v-model="competitorForm.channels" placeholder="Kênh"/><MTextarea v-model="competitorForm.note" placeholder="Ghi chú"/></div></MDialog><MDialog :model-value="Boolean(campaignForm)" :title="campaignForm?.id?'Sửa chiến dịch':'Thêm chiến dịch'" @update:model-value="!$event&&(campaignForm=null)" @confirm="emit('save-campaign',campaignForm);campaignForm=null"><div class="space-y-3"><MInput v-model="campaignForm.name" placeholder="Tên chiến dịch"/><MInput v-model="campaignForm.startDate" type="date" placeholder="Từ ngày"/><MInput v-model="campaignForm.endDate" type="date" placeholder="Đến ngày"/><MInput v-model="campaignForm.message" placeholder="Thông điệp"/><MTextarea v-model="campaignForm.content" placeholder="Nội dung chính"/><MInput v-model="campaignForm.audience" placeholder="Đối tượng"/><MInput v-model="campaignForm.keywords" placeholder="Từ khóa"/><MInput v-model="campaignForm.competitors" placeholder="Đối thủ"/><MTextarea v-model="campaignForm.note" placeholder="Ghi chú"/></div></MDialog></section></template>
